import uvicorn


def main() -> None:
    uvicorn.run("webui.app:app", host="127.0.0.1", port=8000, reload=True)


if __name__ == "__main__":
    main()

{% extends "base.html" %}
{% block content %}
<h1>AI Chat</h1>
<p>WebSocket stream with interrupt support.</p>

<div class="chat-controls">
  <textarea id="question" rows="3" placeholder="Ask question..."></textarea>
  <button id="askBtn" type="button">Send</button>
</div>

<pre id="chatOutput" class="panel"></pre>

<script>
  const output = document.getElementById("chatOutput");
  const askBtn = document.getElementById("askBtn");
  const questionInput = document.getElementById("question");
  const sessionId = crypto.randomUUID();
  const protocol = location.protocol === "https:" ? "wss" : "ws";
  const ws = new WebSocket(`${protocol}://${location.host}/ws/chat/${sessionId}`);

{% extends "base.html" %}
{% block content %}
<h1>Relationships</h1>
<p>Imported architecture relationships.</p>

<pre id="relationships" class="panel">Loading...</pre>

<script>
  fetch("/api/relationships")
    .then((r) => r.json())
    .then((data) => {
      document.getElementById("relationships").textContent = JSON.stringify(data, null, 2);
    })
    .catch((err) => {
      document.getElementById("relationships").textContent = String(err);
    });
</script>
{% endblock %}

{% extends "base.html" %}
{% block content %}
<h1>Context</h1>
<p>Context stats and reindex control.</p>

<div class="row">
  <input id="semanticProfile" type="text" placeholder="semantic profile (optional)">
  <button id="reindexBtn" type="button">Run Reindex</button>
</div>

<pre id="contextStats" class="panel">Loading...</pre>

<script>
  const statsEl = document.getElementById("contextStats");
  const reindexBtn = document.getElementById("reindexBtn");

  async function loadStats() {
    const stats = await fetch("/api/context/stats").then((r) => r.json());
    statsEl.textContent = JSON.stringify(stats, null, 2);
  }

