 {% extends "base.html" %}
 {% block content %}
 <h1>AI Chat</h1>
 <p>WebSocket stream with interrupt support.</p>

+  <style>
+    .interrupt-controls {
+      display: flex;
+      gap: 0.5rem;
+      margin-top: 0.5rem;
+      margin-bottom: 0.5rem;
+    }
+    .interrupt-input {
+      flex: 1;
+    }
+  </style>
+
 <div class="chat-controls">
   <textarea id="question" rows="3" placeholder="Ask question..."></textarea>
   <button id="askBtn" type="button">Send</button>
 </div>

 <pre id="chatOutput" class="panel"></pre>

 <script>
   const output = document.getElementById("chatOutput");
   const askBtn = document.getElementById("askBtn");
   const questionInput = document.getElementById("question");
   const sessionId = crypto.randomUUID();
   const protocol = location.protocol === "https:" ? "wss" : "ws";
   const ws = new WebSocket(`${protocol}://${location.host}/ws/chat/${sessionId}`);

   function append(line) {
     output.textContent += line + "\n";
     output.scrollTop = output.scrollHeight;
   }

   ws.onopen = () => append("[ws] connected");
   ws.onclose = () => append("[ws] closed");
   ws.onerror = () => append("[ws] error");

   ws.onmessage = (event) => {
     const msg = JSON.parse(event.data);
     if (msg.type === "token") {
       output.textContent += msg.text;
       output.scrollTop = output.scrollHeight;
       return;
     }
     if (msg.type === "interrupt") {
-      append("\n[interrupt] SQL review requested. Auto-accept from demo UI.");
-      ws.send(JSON.stringify({
-        type: "interrupt_response",
-        payload: { type: "accept" }
-      }));
+      const sqlQuery = msg.payload?.[0]?.args?.query || "";
+      append(`\n[interrupt] SQL review requested:\n${sqlQuery}`);
+      
+      const container = document.createElement("div");
+      container.className = "interrupt-controls";
+
+      const acceptBtn = document.createElement("button");
+      acceptBtn.textContent = "Accept";
+      
+      const rejectBtn = document.createElement("button");
+      rejectBtn.textContent = "Reject";
+      
+      const inputField = document.createElement("input");
+      inputField.type = "text";
+      inputField.className = "interrupt-input";
+      inputField.placeholder = "Edit query or add feedback...";
+      inputField.value = sqlQuery;
+
+      const editBtn = document.createElement("button");
+      editBtn.textContent = "Edit";
+      
+      const feedbackBtn = document.createElement("button");
+      feedbackBtn.textContent = "Feedback";
+
+      const removeControls = () => {
+        container.remove();
+      };
+
+      acceptBtn.onclick = () => {
+        append("\n[user] Accepted SQL");
+        ws.send(JSON.stringify({ type: "interrupt_response", payload: { type: "accept" } }));
+        removeControls();
+      };
+
+      rejectBtn.onclick = () => {
+        append("\n[user] Rejected SQL");
+        ws.send(JSON.stringify({ type: "interrupt_response", payload: { type: "reject" } }));
+        removeControls();
+      };
+
+      editBtn.onclick = () => {
+        const val = inputField.value.trim();
+        append(`\n[user] Edited SQL: ${val}`);
+        ws.send(JSON.stringify({ type: "interrupt_response", payload: { type: "edit", edited_query: val } }));
+        removeControls();
+      };
+
+      feedbackBtn.onclick = () => {
+        const val = inputField.value.trim();
+        append(`\n[user] Feedback: ${val}`);
+        ws.send(JSON.stringify({ type: "interrupt_response", payload: { type: "response", feedback: val } }));
+        removeControls();
+      };
+
+      container.append(acceptBtn, rejectBtn, inputField, editBtn, feedbackBtn);
+      output.parentNode.insertBefore(container, output.nextSibling);
+      
       return;
     }
     if (msg.type === "transition") {
       append(`\n[transition] ${msg.node}`);
       return;
     }
     if (msg.type === "final") {
       append(`\n[final] status=${msg.status || "unknown"}`);
       if (msg.answer) append(msg.answer);
       if (msg.sql) append(`\n[sql]\n${msg.sql}`);
       return;
     }
     if (msg.type === "error") {
       append(`\n[error] ${msg.message}`);
       return;
     }
     if (msg.type === "done") {
       append("\n[done]");
     }
   };

   askBtn.addEventListener("click", () => {
     const question = questionInput.value.trim();
     if (!question) {
       append("[client] question required");
       return;
     }
     append(`\n[user] ${question}`);
     ws.send(JSON.stringify({ type: "ask", question }));
   });
 </script>
 {% endblock %}

