def __post_init__(self):
    self._load_runtime_settings()

def _load_runtime_settings(self):
    if not self.RUNTIME_SETTINGS_PATH.exists():
        return

    try:
        with open(self.RUNTIME_SETTINGS_PATH, "r") as f:
            data = json.load(f)

        for key, value in data.items():
            if hasattr(self, key) and key not in ["ROOT_DIR", "RUNTIME_SETTINGS_PATH"]:
                setattr(self, key, value)
    except Exception as e:
        logger.error(f"Failed to load runtime settings from {self.RUNTIME_SETTINGS_PATH}: {e}")

def save_runtime_settings(self):
    try:
        self.RUNTIME_SETTINGS_PATH.parent.mkdir(parents=True, exist_ok=True)

        data = {}
        for key, value in self.__dict__.items():
            if key in ["ROOT_DIR", "RUNTIME_SETTINGS_PATH"]:
                continue
            if isinstance(value, Path):
                data[key] = str(value)
            else:
                data[key] = value

        with open(self.RUNTIME_SETTINGS_PATH, "w") as f:
            json.dump(data, f, indent=2)
    except Exception as e:
        logger.error(f"Failed to save runtime settings to {self.RUNTIME_SETTINGS_PATH}: {e}")
        raise

@router.put("/config/app")
def update_app_config(payload: SettingsUpdateRequest) -> dict[str, object]:
    config = AppConfig()
    updated_fields = payload.model_dump(exclude_none=True)

    for key, value in updated_fields.items():
        if hasattr(config, key):
            setattr(config, key, value)

    config.save_runtime_settings()

    return {
        "updated": updated_fields,
        "note": "Settings saved to runtime config.",
    }

