{% extends "base.html" %}
{% block content %}
<style>
  .settings-form {
    display: flex;
    flex-direction: column;
    gap: 1rem;
    max-width: 500px;
    margin-bottom: 2rem;
  }
  .setting-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.5rem;
    background: #f9f9f9;
    border-radius: 4px;
    border: 1px solid #ddd;
  }
  .setting-item label {
    font-weight: bold;
    cursor: pointer;
  }
  .save-btn {
    align-self: flex-start;
  }
  #statusMsg {
    margin-left: 1rem;
    color: green;
  }
</style>

<h1>Settings</h1>
<p>Runtime config settings. Saved to <code>.app_cache/settings.json</code>.</p>

<form id="settingsForm" class="settings-form">
  <div class="setting-item">
    <label for="HUMAN_SQL_REVIEW">HUMAN_SQL_REVIEW</label>
    <input type="checkbox" id="HUMAN_SQL_REVIEW" name="HUMAN_SQL_REVIEW">
  </div>
  <div class="setting-item">
    <label for="EXECUTE_SQL_QUERIES">EXECUTE_SQL_QUERIES</label>
    <input type="checkbox" id="EXECUTE_SQL_QUERIES" name="EXECUTE_SQL_QUERIES">
  </div>
  <div class="setting-item">
    <label for="CONTEXT_AUTO_INDEX_ON_STARTUP">CONTEXT_AUTO_INDEX_ON_STARTUP</label>
    <input type="checkbox" id="CONTEXT_AUTO_INDEX_ON_STARTUP" name="CONTEXT_AUTO_INDEX_ON_STARTUP">
  </div>
  <div class="setting-item">
    <label for="CLI_ASK_RESULT_CONFIRMATION">CLI_ASK_RESULT_CONFIRMATION</label>
    <input type="checkbox" id="CLI_ASK_RESULT_CONFIRMATION" name="CLI_ASK_RESULT_CONFIRMATION">
  </div>

  <div>
    <button type="submit" class="save-btn">Save Settings</button>
    <span id="statusMsg"></span>
  </div>
</form>

<h3>Raw Config Output</h3>
<pre id="settingsOutput" class="panel">Loading...</pre>

<script>
  const form = document.getElementById("settingsForm");
  const output = document.getElementById("settingsOutput");
  const statusMsg = document.getElementById("statusMsg");

  const fields = [
    "HUMAN_SQL_REVIEW",
    "EXECUTE_SQL_QUERIES",
    "CONTEXT_AUTO_INDEX_ON_STARTUP",
    "CLI_ASK_RESULT_CONFIRMATION"
  ];

  async function loadSettings() {
    try {
      const res = await fetch("/api/config/app");
      const data = await res.json();
      output.textContent = JSON.stringify(data, null, 2);

      fields.forEach(f => {
        if (data[f] !== undefined) {
          document.getElementById(f).checked = data[f];
        }
      });
    } catch (err) {
      output.textContent = String(err);
    }
  }

  form.addEventListener("submit", async (e) => {
    e.preventDefault();
    statusMsg.textContent = "Saving...";

    const payload = {};
    fields.forEach(f => {
      payload[f] = document.getElementById(f).checked;
    });

    try {
      const res = await fetch("/api/config/app", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      });
      const data = await res.json();

      if (res.ok) {
        statusMsg.textContent = "Saved!";
        setTimeout(() => statusMsg.textContent = "", 2000);
        await loadSettings();
      } else {
        statusMsg.textContent = "Error saving";
        statusMsg.style.color = "red";
      }
    } catch (err) {
      statusMsg.textContent = "Network error";
      statusMsg.style.color = "red";
    }
  });

  loadSettings();
</script>
{% endblock %}

