+    config = AppConfig()
+    mdl_dir = config.MDL_DIR
+    profiles = []
+    if mdl_dir.exists() and mdl_dir.is_dir():
+        for d in mdl_dir.iterdir():
+            if d.is_dir() and d.name not in (
+                config.MDL_COMMON_SUBDIR,
+                config.MDL_DATABASES_SUBDIR,
+            ):
