function createMessage(type, content) {
  const div = document.createElement("div");
  div.className = `message msg-${type}`;
  if (type === 'user' || type === 'system') {
     div.textContent = content;
  } else if (content) {
     // Simple render markdown formatting for final answer if present
     // Only replace strong/code outside of pre blocks
     let html = content
        .replace(/```sql([\s\S]*?)```/g, '<div class="msg-sql">$1</div>')
        .replace(/```([\s\S]*?)```/g, '<div class="msg-sql">$1</div>')
        .replace(/`([^`]+)`/g, '<code>$1</code>')
        .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');

     // Handle tables
     if (html.includes('|')) {
        html = html.replace(/\|(.+)\|/g, function(match) {
           return '<tr><td>' + match.split('|').filter(Boolean).join('</td><td>') + '</td></tr>';
        });
        html = html.replace(/(<tr>.+<\/tr>\s*)+/g, '<table border="1" style="border-collapse: collapse; width: 100%; margin: 10px 0;">$&</table>');
     }

     div.innerHTML = html.replace(/\n/g, '<br>');
  }
  messagesDiv.appendChild(div);
  messagesDiv.scrollTop = messagesDiv.scrollHeight;
  return div;
}

