function createMessage(type, content) {
  const div = document.createElement("div");
  div.className = `message msg-${type}`;
  if (type === 'user' || type === 'system') {
     div.textContent = content;
  } else if (content) {
     // Simple render markdown formatting for final answer if present
     let html = content
        .replace(/```sql([\s\S]*?)```/g, '<div class="msg-sql">$1</div>')
        .replace(/```([^`]+)```/g, '<div class="msg-sql">$1</div>')
        .replace(/`([^`]+)`/g, '<code>$1</code>')
        .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');

     const rows = html.split('\n');
     let inTable = false;
     let tableHtml = '';
     let finalHtml = [];

     for (let i = 0; i < rows.length; i++) {
       let row = rows[i].trim();
       if (row.startsWith('|') && row.endsWith('|')) {
         if (row.includes('---')) continue;
         if (!inTable) {
           inTable = true;
           tableHtml = '<table border="1" style="border-collapse: collapse; width: 100%; margin: 10px 0;">';
         }
         const cells = row.split('|').slice(1, -1);
         tableHtml += '<tr>';
         cells.forEach(c => tableHtml += `<td style="padding: 5px;">${c.trim()}</td>`);
         tableHtml += '</tr>';
       } else {
         if (inTable) {
           inTable = false;
           tableHtml += '</table>';
           finalHtml.push(tableHtml);
           tableHtml = '';
         }
         finalHtml.push(rows[i]);
       }
     }
     if (inTable) {
       tableHtml += '</table>';
       finalHtml.push(tableHtml);
     }

     div.innerHTML = finalHtml.join('<br>');
  }
  messagesDiv.appendChild(div);
  messagesDiv.scrollTop = messagesDiv.scrollHeight;
  return div;
}

